#include "unity.h"
#include "header.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_swap_basic_two_integers(void) {
    // Setup: two integers with distinct values
    int x = 5;
    int y = 10;

    // Test: call swap
    swap(&x, &y);

    // Assertions: values should be swapped
    TEST_ASSERT_EQUAL_INT(10, x);
    TEST_ASSERT_EQUAL_INT(5, y);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_swap_basic_two_integers);
    return UNITY_END();
}
